from collections import defaultdict
class Solution:
    def overlappingShifts(self, shifts):
        emp = defaultdict(list)
        for e, s, t in shifts:
            emp[e].append((s, t))
        res = []
        for e in sorted(emp):
            ivs = sorted(emp[e])
            events = []
            for s, t in ivs:
                events.append((s, 1)); events.append((t, -1))
            events.sort(key=lambda x: (x[0], x[1]))
            cur = mx = 0
            for _, d in events:
                cur += d; mx = max(mx, cur)
            tot = 0
            for i in range(len(ivs)):
                for j in range(i + 1, len(ivs)):
                    ov = min(ivs[i][1], ivs[j][1]) - max(ivs[i][0], ivs[j][0])
                    if ov > 0: tot += ov
            res.append([e, mx, tot])
        return res

