class Solution {
public:
    vector<vector<long long>> overlappingShifts(vector<vector<long long>>& shifts) {
        map<long long, vector<pair<long long,long long>>> emp;
        for (auto& s : shifts) emp[s[0]].push_back({s[1], s[2]});
        vector<vector<long long>> res;
        for (auto& [e, ivs] : emp) {
            sort(ivs.begin(), ivs.end());
            vector<pair<long long,int>> ev;
            for (auto& [s, t] : ivs) { ev.push_back({s, 1}); ev.push_back({t, -1}); }
            sort(ev.begin(), ev.end());
            long long cur = 0, mx = 0, tot = 0;
            for (auto& [t, d] : ev) { cur += d; mx = max(mx, cur); }
            for (size_t i = 0; i < ivs.size(); i++)
                for (size_t j = i + 1; j < ivs.size(); j++) {
                    long long ov = min(ivs[i].second, ivs[j].second) - max(ivs[i].first, ivs[j].first);
                    if (ov > 0) tot += ov;
                }
            res.push_back({e, mx, tot});
        }
        return res;
    }
};

