class Solution {
    public List<long[]> overlappingShifts(int[][] shifts) {
        TreeMap<Integer, List<int[]>> emp = new TreeMap<>();
        for (int[] s : shifts) emp.computeIfAbsent(s[0], z -> new ArrayList<>()).add(new int[]{s[1], s[2]});
        List<long[]> res = new ArrayList<>();
        for (var en : emp.entrySet()) {
            List<int[]> ivs = en.getValue();
            ivs.sort(Comparator.comparingInt(a -> a[0]));
            List<int[]> ev = new ArrayList<>();
            for (int[] iv : ivs) { ev.add(new int[]{iv[0], 1}); ev.add(new int[]{iv[1], -1}); }
            ev.sort((a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
            long cur = 0, mx = 0, tot = 0;
            for (int[] e2 : ev) { cur += e2[1]; mx = Math.max(mx, cur); }
            for (int i = 0; i < ivs.size(); i++)
                for (int j = i + 1; j < ivs.size(); j++) {
                    long ov = Math.min(ivs.get(i)[1], ivs.get(j)[1]) - Math.max(ivs.get(i)[0], ivs.get(j)[0]);
                    if (ov > 0) tot += ov;
                }
            res.add(new long[]{en.getKey(), mx, tot});
        }
        return res;
    }
}

