var overlappingShifts = function(shifts) {
    const emp = new Map();
    for (const [e, s, t] of shifts) {
        if (!emp.has(e)) emp.set(e, []);
        emp.get(e).push([s, t]);
    }
    const res = [];
    for (const e of [...emp.keys()].sort((a, b) => a - b)) {
        const ivs = emp.get(e).sort((a, b) => a[0] - b[0]);
        const ev = [];
        for (const [s, t] of ivs) { ev.push([s, 1]); ev.push([t, -1]); }
        ev.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
        let cur = 0, mx = 0, tot = 0;
        for (const [, d] of ev) { cur += d; mx = Math.max(mx, cur); }
        for (let i = 0; i < ivs.length; i++)
            for (let j = i + 1; j < ivs.length; j++) {
                const ov = Math.min(ivs[i][1], ivs[j][1]) - Math.max(ivs[i][0], ivs[j][0]);
                if (ov > 0) tot += ov;
            }
        res.push([e, mx, tot]);
    }
    return res;
};
